data.script:
const lines = draft.content.replace(/\r\n?/g, '\n').split('\n');
const title = lines.shift().trim();
if (!title) { context.fail('The first line must contain a task title.'); }
else {
  const notes = lines.join('\n').trim();
  if (title.length > 4000 || notes.length > 10000) { context.fail('The draft exceeds Things URL limits.'); }
  else {
    const url = 'things:///add?show-quick-entry=true&title=' + encodeURIComponent(title) + '&notes=' + encodeURIComponent(notes);
    if (!app.openURL(url)) { context.fail('Could not open Things.'); }
  }
}
